import { sanitizeSvgMarkup } from './html-import.ts';
import type { NewNode } from './doc.ts';
import { hasIcon, iconNameDistance, iconSvg, rankIconNames, iconNames, type IconOptions } from './icons.ts';

/**
 * Icon sets beyond Lucide, one style each, generated by scripts/gen-icon-sets.ts from the published packages into
 * packages/core/src/icon-sets/<set>.json. They are data files, not code: the build copies them next to the CLI bundle
 * (dist/icon-sets/), and the server reads one the first time a search or an insert asks for that set
 * (configureIconSets). The editor and a CLI that never asks carry none of it. A name is `set:name`, such as
 * `tabler:home` or `material-symbols:add_home`; a name without a set is Lucide, as before. Logos of other companies
 * are left out of every set.
 */
export type IconSetId = 'lucide' | 'phosphor' | 'tabler' | 'heroicons' | 'heroicons-solid' | 'material-symbols';

export interface IconSetInfo {
  id: IconSetId;
  name: string;
  license: string;
  url: string;
  /** How the set draws: strokes that follow stroke_width, or filled shapes. */
  kind: 'stroke' | 'fill';
}

interface IconSetData extends IconSetInfo { source: string; viewBox: string; strokeWidth?: number; icons: Record<string, string> }

export const ICON_SETS: IconSetInfo[] = [
  { id: 'lucide', name: 'Lucide', license: 'ISC', url: 'https://lucide.dev', kind: 'stroke' },
  { id: 'phosphor', name: 'Phosphor (regular)', license: 'MIT', url: 'https://phosphoricons.com', kind: 'fill' },
  { id: 'tabler', name: 'Tabler Icons (outline)', license: 'MIT', url: 'https://tabler.io/icons', kind: 'stroke' },
  { id: 'heroicons', name: 'Heroicons (outline)', license: 'MIT', url: 'https://heroicons.com', kind: 'stroke' },
  { id: 'heroicons-solid', name: 'Heroicons (solid)', license: 'MIT', url: 'https://heroicons.com', kind: 'fill' },
  { id: 'material-symbols', name: 'Material Symbols (outlined)', license: 'Apache-2.0', url: 'https://fonts.google.com/icons', kind: 'fill' },
];

/** Reads the JSON text of one set's file, such as `tabler.json`. The server gives one that reads it from disk. */
export type IconSetReader = (file: string) => Promise<string>;

let reader: IconSetReader | null = null;
const loaded = new Map<IconSetId, Promise<IconSetData>>();

/** Where the sets come from. Called once by the server; until then a set beyond Lucide cannot be read. */
export function configureIconSets(read: IconSetReader): void {
  reader = read;
  loaded.clear();
}

export function isIconSet(id: string): id is IconSetId {
  return ICON_SETS.some((s) => s.id === id);
}

async function loadSet(id: Exclude<IconSetId, 'lucide'>): Promise<IconSetData> {
  let p = loaded.get(id);
  if (!p) {
    const read = reader;
    if (!read) throw new Error(`The ${id} icons cannot be read here: no icon set files are configured. Use a Lucide icon.`);
    p = read(`${id}.json`).then((text) => {
      const data = JSON.parse(text) as IconSetData;
      if (data.id !== id || !data.icons || typeof data.icons !== 'object') throw new Error(`${id}.json is not the ${id} icon set.`);
      return data;
    });
    // A file that was missing may be there next time, so a failure is not kept.
    p.catch(() => loaded.delete(id));
    loaded.set(id, p);
  }
  return p;
}

/** A name as its set and its name in the set. Lucide's names have no set in front, and `lucide:` is accepted. */
export function splitIconName(name: string): { set: IconSetId; icon: string } | null {
  const at = name.indexOf(':');
  if (at < 0) return { set: 'lucide', icon: name };
  const set = name.slice(0, at);
  return isIconSet(set) ? { set, icon: name.slice(at + 1) } : null;
}

const full = (set: IconSetId, icon: string) => (set === 'lucide' ? icon : `${set}:${icon}`);

async function namesOf(set: IconSetId): Promise<string[]> {
  return set === 'lucide' ? iconNames() : Object.keys((await loadSet(set)).icons);
}

export async function hasSetIcon(name: string): Promise<boolean> {
  const parts = splitIconName(name);
  if (!parts) return false;
  if (parts.set === 'lucide') return hasIcon(parts.icon);
  return Object.hasOwn((await loadSet(parts.set)).icons, parts.icon);
}

/**
 * Icons of one set, or of every set with `all`, by name and common words, best first, as full names. Across sets the
 * best of each set take turns, so that one large set does not push the others out of the list.
 */
export async function searchSetIcons(query: string, options: { set?: IconSetId | 'all'; limit?: number } = {}): Promise<string[]> {
  const limit = options.limit ?? 30;
  const set = options.set ?? 'lucide';
  if (set !== 'all') return rankIconNames(await namesOf(set), query, limit).map((n) => full(set, n));
  const lists = await Promise.all(ICON_SETS.map(async (s) => rankIconNames(await namesOf(s.id), query, limit).map((n) => full(s.id, n))));
  const out: string[] = [];
  for (let i = 0; out.length < limit && lists.some((l) => i < l.length); i++) for (const l of lists) if (l[i] && out.length < limit) out.push(l[i]!);
  return out;
}

/** For a name that is almost right: by words first, then by spelling, in the set the name says. */
export async function closestSetIcons(name: string, limit = 6): Promise<string[]> {
  const parts = splitIconName(name) ?? { set: 'lucide' as const, icon: name.slice(name.indexOf(':') + 1) };
  const direct = await searchSetIcons(parts.icon.replace(/[-_]/g, ' '), { set: parts.set, limit });
  if (direct.length) return direct;
  const names = await namesOf(parts.set);
  return names.map((n) => ({ n, d: iconNameDistance(parts.icon, n) })).sort((a, b) => a.d - b.d).slice(0, limit).map((x) => full(parts.set, x.n));
}

/**
 * One icon of any set as editable SVG in `currentColor` unless given a colour. A stroked set takes the stroke width,
 * and a filled one fills with the colour. Throws for a name that is not in its set.
 */
export async function setIconSvg(name: string, options: IconOptions = {}): Promise<string> {
  const parts = splitIconName(name);
  if (!parts || !(await hasSetIcon(name))) throw new Error(`There is no icon "${name}". Call icon_search.`);
  if (parts.set === 'lucide') return iconSvg(parts.icon, options);
  const data = await loadSet(parts.set);
  const color = options.color && /^[#\w(),.\s%-]+$/.test(options.color) ? options.color : 'currentColor';
  const width = Number.isFinite(options.strokeWidth) && options.strokeWidth! > 0 ? options.strokeWidth : data.strokeWidth ?? 2;
  const paint = data.kind === 'stroke'
    ? `fill="none" stroke="${color}" stroke-width="${width}" stroke-linecap="round" stroke-linejoin="round"`
    : `fill="${color}"`;
  return sanitizeSvgMarkup(`<svg xmlns="http://www.w3.org/2000/svg" width="100%" height="100%" viewBox="${data.viewBox}" ${paint}>${data.icons[parts.icon]}</svg>`);
}

/** One icon of any set as a layer spec, named by its full name. */
export async function setIconSpec(name: string, options: IconOptions & { size?: number } = {}): Promise<NewNode> {
  const svg = await setIconSvg(name, options);
  const size = options.size ?? 24;
  return { type: 'svg', tag: 'svg', name, svg, style: { width: `${size}px`, height: `${size}px`, flexShrink: '0' } };
}

/** How many icons each set has, for listing them. */
export async function iconSetCounts(): Promise<(IconSetInfo & { icons: number; source: string })[]> {
  return Promise.all(ICON_SETS.map(async (s) => {
    if (s.id === 'lucide') return { ...s, icons: iconNames().length, source: 'lucide-react' };
    const data = await loadSet(s.id);
    return { ...s, icons: Object.keys(data.icons).length, source: data.source };
  }));
}
